// Des: Tests for read lists, Messenger replies, buyer inquiries, listing extras, sale detection
// Flo: lists print numbered lines > unread threads answered for known contacts only > market actions (available, relist, delete, share) > sale scan proposes sold
// I/O: real local Chrome (skipped when absent) + mock site > pass or fail (no leaks)
// Run: zig build test -Dfile=ru-read-main-test.zig
// ===================================================================
const std = @import("std"); const rigz = @import("te-rigz-brow.zig"); const task = @import("ru-task-runn.zig"); const rdm = @import("ru-read-main.zig"); const mark = @import("ru-mark-list.zig");
fn has(rig: *rigz.Rig, needle: []const u8) bool { return std.mem.find(u8, rig.sink.items, needle) != null; }
test "read lists print numbered lines and change nothing" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); var cx = rig.ctx(.read); try std.testing.expectEqual(@as(u32, 2), try rdm.readRun(&cx, "noti")); try std.testing.expect(has(&rig, "1. Is this still available?")); try std.testing.expectEqual(@as(u32, 3), try rdm.readRun(&cx, "requests")); try std.testing.expectEqual(@as(u32, 2), try rdm.readRun(&cx, "inbox")); try std.testing.expect(has(&rig, "Unread conversation with Ann")); try std.testing.expectEqual(@as(u32, 2), try rdm.readRun(&cx, "market-inbox")); try std.testing.expectError(error.NoJob, rdm.readRun(&cx, "zzz")); try std.testing.expectEqual(@as(usize, 0), rig.mock.recCnt()); }
test "thread id is taken from the link" { try std.testing.expectEqualStrings("42", rdm.threadId("/messages/t/42").?); try std.testing.expectEqualStrings("42", rdm.threadId("https://www.facebook.com/messages/t/42/?x=1").?); try std.testing.expect(rdm.threadId("/groups/1/") == null); try std.testing.expect(rdm.threadId("/messages/t/") == null); }
test "Messenger reply answers unread threads of known contacts, skips new people" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); var cx = rig.ctx(.live); try std.testing.expectEqual(@as(u32, 0), try rdm.msgrReply(&cx, .{}, false)); try std.testing.expect(has(&rig, "skipped thread 42 (NeedApprove)")); try rig.store.knowAdd("42", 1); cx = rig.ctx(.live); try std.testing.expectEqual(@as(u32, 1), try rdm.msgrReply(&cx, .{}, false)); try std.testing.expect(rig.waitPre("dm|", 4000)); try std.testing.expectEqual(@as(u32, 0), try rdm.msgrReply(&cx, .{}, false)); }
test "buyer inquiries use the inquiry templates" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); try rig.store.knowAdd("51", 1); var cx = rig.ctx(.live); try std.testing.expectEqual(@as(u32, 1), try rdm.msgrReply(&cx, .{}, true)); try std.testing.expect(rig.waitPre("dm|", 4000)); const got = rig.mock.recFind("dm").?; try std.testing.expect(std.mem.find(u8, got, "available") != null or std.mem.find(u8, got, "reply shortly") != null); }
test "market extras: available, relist, delete (needs force), share to groups, ledger groups" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); rig.conf.capz_mark_dayz = 20; _ = try rig.store.ledgAdd("L1", "Red bike", "", 1000); _ = try rig.store.ledgSet("Red bike", "sold", 1500); var cx = rig.ctx(.live); try std.testing.expectEqual(task.Out.done, try mark.availRun(&cx, .{ .title = "red bike" })); try std.testing.expect(rig.waitPre("avail|Red bike", 4000)); try std.testing.expectEqual(task.Out.done, try mark.relistRun(&cx, .{ .title = "Blue desk" })); try std.testing.expect(rig.waitPre("relist|Blue desk", 4000)); try std.testing.expectError(error.NeedApprove, mark.deleteRun(&cx, .{ .title = "Blue desk" })); cx = rig.ctx(.force); try std.testing.expectEqual(task.Out.done, try mark.deleteRun(&cx, .{ .title = "Blue desk" })); try std.testing.expect(rig.waitPre("mdele|Blue desk", 4000)); try std.testing.expect(rig.waitPre("pg|Confirm", 4000)); cx = rig.ctx(.live); try std.testing.expectEqual(@as(u32, 2), try mark.shareRun(&cx, .{ .title = "Red bike", .group = "Bike Club HN, Home Goods" })); try std.testing.expect(rig.waitPre("pg|Home Goods", 4000)); var aren = std.heap.ArenaAllocator.init(std.testing.allocator); defer aren.deinit(); const rows = try rig.store.ledgList(aren.allocator()); try std.testing.expectEqualStrings("live", rows[0].st); try std.testing.expectEqualStrings("Bike Club HN; Home Goods", rows[0].grou); }
test "sale scan proposes sold from group posts and marks it only with --force" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); _ = try rig.store.ledgAdd("L1", "Red bike", "Bike Club", 1000); _ = try rig.store.ledgAdd("L2", "Blue desk", "Home", 1000); var cx = rig.ctx(.live); try std.testing.expectEqual(@as(u32, 1), try mark.saleScan(&cx, .{ .url = "/groups/89/" })); try std.testing.expect(has(&rig, "sale seen for \"Red bike\"")); try std.testing.expectEqual(@as(usize, 0), rig.mock.recNum("sold")); cx = rig.ctx(.force); try std.testing.expectEqual(@as(u32, 1), try mark.saleScan(&cx, .{ .url = "/groups/89/" })); try std.testing.expect(rig.waitPre("sold|Red bike", 4000)); var aren = std.heap.ArenaAllocator.init(std.testing.allocator); defer aren.deinit(); const rows = try rig.store.ledgList(aren.allocator()); try std.testing.expectEqualStrings("sold", rows[0].st); try std.testing.expectEqualStrings("live", rows[1].st); }
test "listing wizard fills category, condition, location, then Next and Publish" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); rig.conf.path_mark_crea = "/marketplace/create/wizard"; var cx = rig.ctx(.live); try std.testing.expectEqual(task.Out.done, try mark.listRun(&cx, .{ .title = "Wizard bike", .price = "500", .desc = "Nice", .catg = "Bikes", .cond = "Used", .loca = "Hanoi" })); try std.testing.expect(rig.waitPre("opt|Category=Bikes", 4000)); try std.testing.expect(rig.waitPre("opt|Condition=Used", 4000)); try std.testing.expect(rig.waitPre("btn|Next|", 4000)); try std.testing.expect(rig.waitPre("btn|Publish|Wizard bike|500|Nice|Hanoi", 4000)); }
